'use client'

import * as React from 'react'
import { cn, toggleMachine } from "@/lib/utils"
import { cva, type VariantProps } from 'class-variance-authority'

import { useMachine } from '../hooks/use-machine'

export const toggleVariants = cva(
  'inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground',
  {
    variants: {
      variant: {
        default: 'bg-transparent',
        outline: 'border border-input bg-transparent hover:bg-accent hover:text-accent-foreground',
      },
      size: {
        default: 'h-10 px-3',
        sm: 'h-9 px-2.5',
        lg: 'h-11 px-5',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  }
)

const Toggle = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> &
    VariantProps<typeof toggleVariants> & {
      pressed?: boolean
      defaultPressed?: boolean
      onPressedChange?: (pressed: boolean) => void
    }
>(({ className, pressed, defaultPressed, onPressedChange, variant, size, ...props }, ref) => {
  const initialPressed = pressed !== undefined ? pressed : defaultPressed

  const [state, send] = useMachine(toggleMachine, {
    context: {
      pressed: initialPressed !== undefined ? initialPressed : false,
    },
  })

  // Sync
  React.useEffect(() => {
    if (pressed !== undefined && pressed !== state.context.pressed) {
      send({ type: 'PRESSED.SET', pressed })
    }
  }, [pressed, send, state.context.pressed])

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    send({ type: 'PRESSED.TOGGLE' })
    // We assume toggle machine toggles correctly.
    // Ideally we get next state to callback.
    const nextPressed = !state.context.pressed
    onPressedChange?.(nextPressed)
    props.onClick?.(e)
  }

  return (
    <button
      ref={ref}
      data-slot="toggle"
      data-state={state.context.pressed ? 'on' : 'off'}
      aria-pressed={state.context.pressed}
      type="button"
      className={cn(toggleVariants({ variant, size, className }))}
      onClick={handleClick}
      {...props}
    />
  )
})
Toggle.displayName = 'Toggle'

export { Toggle }

import { type ComputedRef, inject, provide } from 'vue'
import type { ToggleGroupApi, ToggleVariants } from "@/lib/utils"

export type ToggleGroupContextValue = {
    variant?: ToggleVariants['variant']
    size?: ToggleVariants['size']
    api: ComputedRef<ToggleGroupApi>
    type?: 'single' | 'multiple'
    disabled?: boolean
}

export const ToggleGroupContextKey = Symbol('ToggleGroupContext')

export function provideToggleGroupContext(context: ToggleGroupContextValue) {
    provide(ToggleGroupContextKey, context)
}

export function useToggleGroupContext() {
    const context = inject<ToggleGroupContextValue>(ToggleGroupContextKey)
    if (!context) {
        throw new Error('useToggleGroupContext must be used within a ToggleGroupProvider')
    }
    return context
}

import { computed, type ComputedRef } from 'vue'
import { toggleGroupMachine, toggleGroupConnect, type ToggleGroupApi } from "@/lib/utils"
import { useMachine, normalizeProps } from '@zag-js/vue'

export type UseToggleGroupProps = {
    id?: string
    value?: string[]
    defaultValue?: string[]
    disabled?: boolean
    multiple?: boolean
    loop?: boolean
    onValueChange?: (details: { value: string[] }) => void
}

export function useToggleGroup(props: UseToggleGroupProps) {
    const service = useMachine(toggleGroupMachine, {
        value: props.value,
        defaultValue: props.defaultValue,
        disabled: props.disabled,
        multiple: props.multiple,
        onValueChange: props.onValueChange,
    })

    return computed(() => toggleGroupConnect(service, normalizeProps))
}

import { computed } from 'vue'
import { toggleMachine, toggleConnect } from "@/lib/utils"
import { useMachine, normalizeProps } from '@zag-js/vue'

type ToggleProps = {
    pressed?: boolean
    defaultPressed?: boolean
    disabled?: boolean
    onPressedChange?: (pressed: boolean) => void
}

export function useToggle(props: ToggleProps = {}) {
    const service = useMachine(toggleMachine, {
        pressed: props.pressed,
        defaultPressed: props.defaultPressed,
        disabled: props.disabled,
        onPressedChange: props.onPressedChange,
    })

    return computed(() => toggleConnect(service, normalizeProps))
}

import { setupToggleMachine } from './use-toggle'

type MachineEvent = string | {
    type: string
    [key: string]: string | number | boolean | string[] | number[] | null | undefined
}

type WeappToggleApi = {
    buttonProps?: {
        onClick?: () => void
    }
}

type WeappService = {
    setContext: (context: {
        pressed?: boolean
        disabled?: boolean
    }) => void
}

type WeappToggleInternal = WechatMiniprogram.Component.InstanceMethods<WechatMiniprogram.IAnyObject> & {
    _service?: WeappService
    _cleanup?: () => void
    _send?: (event: MachineEvent) => void
    data: {
        api: WeappToggleApi
    }
    properties: {
        pressed: boolean
        disabled: boolean
        id: string
        extClass: string
    }
}

Component({
    options: {
        styleIsolation: 'apply-shared',
        pureDataPattern: /^_/,
    },

    properties: {
        pressed: { type: Boolean, value: false },
        disabled: { type: Boolean, value: false },
        id: { type: String, value: 'toggle' },
        extClass: { type: String, value: '' },
    },

    data: {
        api: {} as WeappToggleApi,
        className: '',
    },

    lifetimes: {
        attached() {
            const self = this as WeappToggleInternal
            const { service, cleanup, send } = setupToggleMachine(this, {
                id: this.properties.id,
                pressed: this.properties.pressed,
                disabled: this.properties.disabled,
                onPressedChange: (details) => {
                    this.triggerEvent('change', details)
                }
            })

            self._service = service as WeappService
            self._cleanup = cleanup
            self._send = send as (event: MachineEvent) => void
        },
        detached() {
            const self = this as WeappToggleInternal
            self._cleanup?.()
        },
    },

    observers: {
        'state': function (state) {
            const self = this as WeappToggleInternal
            if (!state || !self._send) return
            const { connect } = setupToggleMachine(this, { id: this.properties.id })
            const api = connect(state, self._send) as WeappToggleApi
            this.setData({ api, className: this.properties.extClass })
        },

        'pressed': function (val) {
            const self = this as WeappToggleInternal
            if (self._service) {
                self._service.setContext({ pressed: val })
            }
        },
    },

    methods: {
        onTap() {
            const self = this as WeappToggleInternal
            self.data.api.buttonProps?.onClick?.()
        },
    },
})

import { setupToggleGroupMachine } from './use-toggle-group'

type WeappToggleGroupApi = {
  value?: string[]
  setValue?: (value: string[]) => void
}

type WeappService = {
  setContext: (context: Record<string, object>) => void
}

type ToggleGroupTapEvent = WechatMiniprogram.BaseEvent & {
  currentTarget: {
    dataset: {
      value?: string
    }
  }
}

type WeappToggleGroupInternal = WechatMiniprogram.Component.InstanceMethods<WechatMiniprogram.IAnyObject> & {
  _service?: WeappService
  _cleanup?: () => void
  _send?: (event: object) => void
  data: {
    api: WeappToggleGroupApi
  }
  properties: {
    value: string[]
    multiple: boolean
    disabled: boolean
    loop: boolean
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    value: { type: Array, value: [] },
    multiple: { type: Boolean, value: false },
    disabled: { type: Boolean, value: false },
    loop: { type: Boolean, value: true },
    id: { type: String, value: 'toggle-group' },
    extClass: { type: String, value: '' },
  },

  data: {
    api: {} as WeappToggleGroupApi,
    className: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappToggleGroupInternal
      const { service, cleanup, send } = setupToggleGroupMachine(this, {
        id: this.properties.id,
        value: this.properties.value,
        multiple: this.properties.multiple,
        disabled: this.properties.disabled,
        loop: this.properties.loop,
        onValueChange: (details) => {
          this.triggerEvent('change', details)
        }
      })

      self._service = service as WeappService
      self._cleanup = cleanup
      self._send = send as (event: object) => void
    },
    detached() {
      const self = this as WeappToggleGroupInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappToggleGroupInternal
      if (!state || !self._send) return
      const { connect } = setupToggleGroupMachine(this, { id: this.properties.id })
      const api = connect(state, self._send) as WeappToggleGroupApi
      this.setData({ api, className: this.properties.extClass })
    },

    'value': function (val) {
      const self = this as WeappToggleGroupInternal
      if (self._service) {
        self._service.setContext({ value: val })
      }
    },
  },

  methods: {
    onItemTap(e: ToggleGroupTapEvent) {
      const self = this as WeappToggleGroupInternal
      const value = e.currentTarget.dataset.value
      if (value && self.data.api.setValue) {
        const currentValue = self.data.api.value || []
        if (this.properties.multiple) {
          const newValue = currentValue.includes(value)
            ? currentValue.filter((v) => v !== value)
            : [...currentValue, value]
          self.data.api.setValue(newValue)
        } else {
          self.data.api.setValue([value])
        }
      }
    },
  },
})
